import{_ as t}from"./chunks/led-battery-levels.BJDA0Ncv.js";import{_ as a}from"./chunks/led-charging.B18WnYb9.js";import{af as r,z as o,J as i,ab as s}from"./chunks/framework.C1QHhBQn.js";const n="/docs/pr/40/images/devices/general/led-restart.svg",y=JSON.parse('{"title":"LEDs on Pro PR2, Zero ZE2 and Enviro EN2","description":"","frontmatter":{"aside":true},"headers":[],"relativePath":"guides/tracker-leds.md","filePath":"guides/tracker-leds.md"}'),d={name:"guides/tracker-leds.md"};function h(l,e,c,p,g,u){return o(),i("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794235425000"},[...e[0]||(e[0]=[s('<h1 id="leds-on-pro-pr2-zero-ze2-and-enviro-en2" tabindex="-1">LEDs on Pro PR2, Zero ZE2 and Enviro EN2 <a class="header-anchor" href="#leds-on-pro-pr2-zero-ze2-and-enviro-en2" aria-label="Permalink to &quot;LEDs on Pro PR2, Zero ZE2 and Enviro EN2&quot;">​</a></h1><p>This guide covers <strong>Pro PR2 (firmware ProN, device ID prefix 20), Zero ZE2 (ZeroN, prefix 19) and Enviro EN2 (EnviroN, prefix 26)</strong>. These models have four battery indicators and two separate GPS and mobile-network indicators. Check the model and device ID before using this guide.</p><p><strong>This is not a guide to Pro PR3 or Zero ZE3.</strong> Those models have four MCU-controlled indicators without the separate GPS and mobile-network pairs described here. Use the <a href="/docs/pr/40/guides/pro3-leds">Pro3 LED guide</a> for PR3. Do not interpret their four lights using the status information below. Vehicle, RTK and other product families also use different displays.</p><h2 id="identify-your-model-and-revision" tabindex="-1">Identify your model and revision <a class="header-anchor" href="#identify-your-model-and-revision" aria-label="Permalink to &quot;Identify your model and revision&quot;">​</a></h2><h3 id="pro-pr2" tabindex="-1">Pro PR2 <a class="header-anchor" href="#pro-pr2" aria-label="Permalink to &quot;Pro PR2 {#pro-pr2}&quot;">​</a></h3><p>ProN/PR2 has four battery indicators and separate GPS and mobile-network diagnostics. The status lights use red plus an amber or yellow channel depending on the board revision. The <a href="#two-red-lights-and-four-orange-lights-after-a-restart">restart example below</a> is specific to PR2. This is a legacy product; its <a href="/docs/pr/40/devices/pro/">device page and specification</a> remain available.</p><h3 id="zero-ze2" tabindex="-1">Zero ZE2 <a class="header-anchor" href="#zero-ze2" aria-label="Permalink to &quot;Zero ZE2 {#zero-ze2}&quot;">​</a></h3><p>ZeroN/ZE2 uses the same battery and diagnostic logic. Revision 05 uses yellow and red diagnostic LEDs. Do not assume that a firmware channel named G means a physically green light. Follow the case icons to identify battery, GPS and mobile-network indicators. The <a href="/docs/pr/40/devices/zero/">Zero device page</a> is for ZE2, not <a href="/docs/pr/40/guides/ze3-leds">ZE3</a>.</p><h3 id="enviro-en2" tabindex="-1">Enviro EN2 <a class="header-anchor" href="#enviro-en2" aria-label="Permalink to &quot;Enviro EN2 {#enviro-en2}&quot;">​</a></h3><p>EnviroN/EN2 uses the shared battery and diagnostic logic, but the exact diagnostic colours must be checked against the supplied board revision. Do not choose a colour chart from ProN or Zero just because the case has six indicators. See the <a href="/docs/pr/40/devices/enviro/">Enviro device page</a> for the model specification, and ask support if the indicator colours differ from your supplied instructions.</p><h2 id="two-red-lights-and-four-orange-lights-after-a-restart" tabindex="-1">Two red lights and four orange lights after a restart <a class="header-anchor" href="#two-red-lights-and-four-orange-lights-after-a-restart" aria-label="Permalink to &quot;Two red lights and four orange lights after a restart&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">This can be normal</p><p>On a Pro PR2, two red status lights together with all four orange battery lights can appear during a restart. This pattern alone does not mean that the tracker is faulty, or that its battery is full.</p></div><figure><img src="'+n+'" alt="Six-indicator restart example: four orange battery lights on the left, followed by red GPS and mobile-network lights. The diagram labels every light and is not a fault code." tabindex="0"><figcaption>Six-indicator restart example: four orange battery lights on the left, followed by red GPS and mobile-network lights. The diagram labels every light and is not a fault code.</figcaption></figure><p>The tracker can restart automatically as well as after a reset. Startup lights may change or run across the battery indicators before the normal status display returns. The exact sequence depends on the hardware, firmware and reason for the restart.</p><p><strong>What should I do?</strong></p><ol><li>Let the tracker finish starting and give it a couple of minutes to communicate. Avoid repeatedly resetting it just because the lights are red.</li><li>Check its latest communication or update time in the app or web portal. A recent successful update is more useful than a snapshot of the lights. An old location on the map does not by itself show whether the tracker has just communicated.</li><li>If updates do not resume, check the charge, data plan and mobile coverage, then follow <a href="/docs/pr/40/faq/troubleshooting#why-is-my-tracker-not-transmitting">tracker troubleshooting</a>. For a GPS test, place it outside with a clear view of the sky.</li></ol><p>If the same pattern persists, keeps returning, or the tracker is not communicating, <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">contact support</a>. Include the device ID, when you saw it, whether it was on charge, its last update time, and a short video showing whether the lights are steady or flashing.</p><h2 id="reading-the-normal-display" tabindex="-1">Reading the normal display <a class="header-anchor" href="#reading-the-normal-display" aria-label="Permalink to &quot;Reading the normal display&quot;">​</a></h2><p>The diagrams are illustrative layouts. Use the icons on the case to identify the lights. The four battery lights are separate from the GPS and mobile-network lights. Red status lights are diagnostic information, not a general device-failure warning.</p><p>A short button press shows the status briefly. Lights may also appear during startup, charging or other device activity. When the tracker is unplugged and resting, the lights normally go out to save power. <strong>No lights does not necessarily mean that the tracker is off or the battery is empty.</strong></p><h3 id="battery-indicators" tabindex="-1">Battery indicators <a class="header-anchor" href="#battery-indicators" aria-label="Permalink to &quot;Battery indicators&quot;">​</a></h3><p>A short status-button press normally shows the battery level briefly. The four indicators use these approximate bands:</p><table tabindex="0"><thead><tr><th>Battery level</th><th>Normal battery display</th></tr></thead><tbody><tr><td>Below 20%</td><td>First indicator flashes when showing status off charge</td></tr><tr><td>20% to below 40%</td><td>1 indicator</td></tr><tr><td>40% to below 60%</td><td>2 indicators</td></tr><tr><td>60% to below 80%</td><td>3 indicators</td></tr><tr><td>80% or more</td><td>4 indicators</td></tr></tbody></table><p>These bands apply to the normal battery display only. Startup, alerts and application-controlled patterns can use the same lights for a different reason. Four lights are not an exact 100% reading.</p><figure><img src="'+t+'" alt="Illustrated battery bands: below 20 percent the first indicator flashes off charge; at least 20, 40, 60 and 80 percent shows one, two, three and four indicators." tabindex="0"><figcaption>Illustrated battery bands: below 20 percent the first indicator flashes off charge; at least 20, 40, 60 and 80 percent shows one, two, three and four indicators.</figcaption></figure><h3 id="gps-and-mobile-network-indicators" tabindex="-1">GPS and mobile-network indicators <a class="header-anchor" href="#gps-and-mobile-network-indicators" aria-label="Permalink to &quot;GPS and mobile-network indicators&quot;">​</a></h3><p>Use the model/revision notes above to identify the <strong>secondary diagnostic colour</strong>. It is not universally green. Both channels can be on together; this does not establish a third, universal mixed colour.</p><table tabindex="0"><thead><tr><th>Mobile-network indicator</th><th>What the standard display can mean</th></tr></thead><tbody><tr><td>Red only</td><td>Flight mode is enabled, or signal strength is zero/unknown while the connection is not open</td></tr><tr><td>Red and secondary colour together</td><td>One signal bar is reported and the connection is not open, with flight mode off</td></tr><tr><td>Secondary colour only</td><td>At least two signal bars are reported or the connection is open, with flight mode off</td></tr></tbody></table><p>The mobile indicator is not confirmation that data reached the server. Check the latest successful communication in the app or portal.</p><table tabindex="0"><thead><tr><th>GPS indicator while the receiver is awake</th><th>What the standard display can mean</th></tr></thead><tbody><tr><td>Red only</td><td>No fix yet, before the waiting-for-fix stage</td></tr><tr><td>Red and secondary colour together</td><td>Waiting for a fix, without a lock yet</td></tr><tr><td>Secondary colour only</td><td>A fix is available, or the receiver has moved beyond the waiting-for-fix stage</td></tr></tbody></table><p>When GPS is asleep, its indicator can reflect whether the <strong>previous</strong> fix attempt failed rather than whether there is a live fix now. A secondary-colour light alone is therefore not a guarantee of a current accurate location. Check the location timestamp and accuracy in the app or portal.</p><h2 id="charging-patterns" tabindex="-1">Charging patterns <a class="header-anchor" href="#charging-patterns" aria-label="Permalink to &quot;Charging patterns&quot;">​</a></h2><ul><li>Below about 95%, the highest lit battery indicator blinks, roughly one second on and one second off. At very low charge, the first indicator blinks.</li><li>At about 95% or above, the normal charging display becomes steady. This means a high charge level, not an exact 100% reading.</li><li>When unplugged and resting, the lights normally go out after any temporary status display finishes. A button press, startup or other activity can still light them.</li></ul><p>These are the standard battery-bar patterns. They are not the RGB charging colours used by RH2.</p><figure><img src="'+a+'" alt="Charging example at three bars: two steady battery lights and a third that alternates on and off every second. This animation is shown as two static frames." tabindex="0"><figcaption>Charging example at three bars: two steady battery lights and a third that alternates on and off every second. This animation is shown as two static frames.</figcaption></figure><p>This guide describes the standard six-indicator display. Custom applications, remote LED control, alarms and other hardware versions can change the lights. If your tracker has a different layout, choose the matching model in the <a href="/docs/pr/40/guides/leds">LED guide</a> or ask support.</p>',36)])])}const w=r(d,[["render",h]]);export{y as __pageData,w as default};
